#include "../../support.hpp"
namespace algs {
template<class T>struct LinkedListNode{T value;std::shared_ptr<LinkedListNode>next;explicit LinkedListNode(T v):value(std::move(v)){} };template<class T>class LinkedList{using Node=LinkedListNode<T>;std::shared_ptr<Node>head,tail;int length=0;std::shared_ptr<Node>nodeAt(int i)const{auto n=head;while(i--)n=n->next;return n;}public:static LinkedList from(const std::vector<T>&v){LinkedList l;for(auto&x:v)l.append(x);return l;}int size()const{return length;}std::optional<T>first()const{return head?std::optional<T>(head->value):std::optional<T>{};}std::optional<T>last()const{return tail?std::optional<T>(tail->value):std::optional<T>{};}LinkedList&append(T v){auto n=std::make_shared<Node>(std::move(v));if(tail)tail->next=n;else head=n;tail=n;++length;return *this;}LinkedList&prepend(T v){auto n=std::make_shared<Node>(std::move(v));n->next=head;head=n;if(!tail)tail=n;++length;return *this;}LinkedList&insertAt(int i,T v){if(i<0||i>length)throw std::out_of_range("Index is out of bounds");if(i==0)return prepend(v);if(i==length)return append(v);auto prev=nodeAt(i-1),n=std::make_shared<Node>(v);n->next=prev->next;prev->next=n;++length;return *this;}std::optional<T>get(int i)const{return i<0||i>=length?std::optional<T>{}:nodeAt(i)->value;}int indexOf(const T&v)const{int i=0;for(auto n=head;n;n=n->next,++i)if(n->value==v)return i;return -1;}template<class F>std::optional<T>find(F f)const{for(auto n=head;n;n=n->next)if(f(n->value))return n->value;return {};}std::optional<T>removeAt(int i){if(i<0||i>=length)return {};std::shared_ptr<Node>removed;if(i==0){removed=head;head=head->next;if(!head)tail.reset();}else{auto prev=nodeAt(i-1);removed=prev->next;prev->next=removed->next;if(removed==tail)tail=prev;}--length;return removed->value;}bool remove(const T&v){int i=indexOf(v);if(i<0)return false;removeAt(i);return true;}LinkedList&reverse(){std::shared_ptr<Node>prev;auto cur=head;tail=cur;while(cur){auto next=cur->next;cur->next=prev;prev=cur;cur=next;}head=prev;return *this;}std::vector<T>toArray()const{std::vector<T>r;for(auto n=head;n;n=n->next)r.push_back(n->value);return r;}};
}
